<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';$userId=(int)current_user()['user_id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$skillId=(int)($_POST['skill_id']??0);$projectId=(int)($_POST['project_id']??0);$type=$_POST['evidence_type']??'description';$title=trim($_POST['title']??'');$link=trim($_POST['evidence_url']??'');$description=trim($_POST['description']??'');$validTypes=['github','portfolio','project_link','document_link','description'];if($title==='')$errors[]='Enter a title for your evidence.';if(!in_array($type,$validTypes,true))$errors[]='Select a valid evidence type.';if($link!==''&&!filter_var($link,FILTER_VALIDATE_URL))$errors[]='Enter a valid URL, including https://.';if(!$skillId)$errors[]='Choose the skill this evidence demonstrates.';$check=$pdo->prepare('SELECT skill_id FROM skills WHERE skill_id=?');$check->execute([$skillId]);if(!$check->fetchColumn())$errors[]='Selected skill was not found.';if($projectId){$check=$pdo->prepare('SELECT project_id FROM projects WHERE project_id=?');$check->execute([$projectId]);if(!$check->fetchColumn())$errors[]='Selected project was not found.';}
if(!$errors){$st=$pdo->prepare('INSERT INTO evidence_submissions (user_id,skill_id,project_id,evidence_type,title,evidence_url,description) VALUES (?,?,?,?,?,?,?)');$st->execute([$userId,$skillId,$projectId?:null,$type,$title,$link?:null,$description?:null]);award_achievement($pdo,$userId,'FIRST_EVIDENCE');$mentors=$pdo->query("SELECT user_id FROM users WHERE role IN ('mentor','admin') AND account_status='active'")->fetchAll(PDO::FETCH_COLUMN);foreach($mentors as $mentorId)create_notification($pdo,(int)$mentorId,'New evidence to review',current_user()['full_name'].' submitted: '.$title,'evidence','mentor/dashboard.php');flash('Evidence submitted. A mentor or reviewer can now review it.');redirect('evidence/index.php');}}
$skills=$pdo->query('SELECT skill_id,skill_name FROM skills ORDER BY skill_name')->fetchAll();$projects=$pdo->query('SELECT project_id,title FROM projects WHERE is_active=1 ORDER BY title')->fetchAll();$st=$pdo->prepare('SELECT e.*,s.skill_name,p.title project_title FROM evidence_submissions e JOIN skills s ON s.skill_id=e.skill_id LEFT JOIN projects p ON p.project_id=e.project_id WHERE e.user_id=? ORDER BY e.submitted_at DESC');$st->execute([$userId]);$rows=$st->fetchAll();$pageTitle='My evidence';$active='passport';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Show what you can do</span><h1 class="h1">Skill evidence</h1><p>Share project work, portfolio links or practical descriptions for mentor review.</p></div></div><div class="grid grid-2" style="align-items:start"><form class="card form-section" method="post"><?=csrf_field()?><h3 class="h3" style="margin-bottom:18px">Submit new evidence</h3><?php if($errors):?><div class="alert alert-error"><?=implode('<br>',array_map('h',$errors))?></div><?php endif;?><div class="field"><label>Evidence title *</label><input class="input" name="title" required maxlength="180" placeholder="e.g. AWS static website deployment"></div><div class="field" style="margin-top:14px"><label>Skill demonstrated *</label><select class="select" name="skill_id" required><option value="">Choose a skill</option><?php foreach($skills as $s):?><option value="<?=(int)$s['skill_id']?>"><?=h($s['skill_name'])?></option><?php endforeach;?></select></div><div class="field" style="margin-top:14px"><label>Related project (optional)</label><select class="select" name="project_id"><option value="">Not linked to a catalogue project</option><?php foreach($projects as $p):?><option value="<?=(int)$p['project_id']?>" <?=(isset($_GET['project_id'])&&(int)$_GET['project_id']===(int)$p['project_id']?'selected':'')?>><?=h($p['title'])?></option><?php endforeach;?></select></div><div class="field" style="margin-top:14px"><label>Evidence type</label><select class="select" name="evidence_type"><option value="github">GitHub repository</option><option value="portfolio">Portfolio</option><option value="project_link">Project link</option><option value="document_link">Document link</option><option value="description">Written description</option></select></div><div class="field" style="margin-top:14px"><label>URL (optional)</label><input class="input" type="url" name="evidence_url" placeholder="https://..."></div><div class="field" style="margin-top:14px"><label>What did you build or demonstrate?</label><textarea class="textarea" name="description" placeholder="Describe your contribution, tools used and what you learned."></textarea></div><div class="form-actions"><button class="btn btn-primary">Submit for review →</button></div><p class="tiny muted">Do not submit passwords, private tokens or confidential project data. Only share links you are comfortable making available to reviewers.</p></form><section class="card card-pad"><div class="panel-title"><h3>Submission history</h3><span class="pill pill-blue"><?=count($rows)?> submissions</span></div><?php foreach($rows as $r):?><div class="verified-skill"><div><strong><?=h($r['title'])?></strong><p><?=h($r['skill_name'])?><?= $r['project_title']?' · '.h($r['project_title']):''?></p><span class="tiny muted"><?=date('d M Y',strtotime($r['submitted_at']))?></span></div><span class="pill <?=$r['status']==='verified'?'pill-green':($r['status']==='rejected'?'pill-red':'pill-amber')?>"><?=h(ucwords(str_replace('_',' ',$r['status'])))?></span></div><?php endforeach;?><?php if(!$rows):?><div class="empty-state" style="padding:35px 10px"><div class="empty-icon">⌑</div><h2>No evidence yet</h2><p>Submit your first project or practical work to start building your proof-based passport.</p></div><?php endif;?></section></div></div></main><?php include __DIR__.'/../includes/footer.php';?>
